/* ---------- поиск и показ ---------- */
(function(){
 const STOP=new Set("как где что мне для это на в и или по из у с к за ли ни не мы вы я он она они можно нужно надо хочу хочется сделать делать делаю нажать куда чтобы если то же бы".split(" ")),
  KKSTOP=new Set("қалай қайда не мен үшін бұл және немесе бойынша керек болады".split(" ")),
  letters=/[a-zа-яёәғқңөұүһі0-9]+/g,
  words=s=>String(s||"").toLowerCase().replace(/ё/g,"е").match(letters)||[],
  stem=w=>w.length>5?w.slice(0,5):w,
  role=()=>own()?"o":({admin:"a",operator:"p",florist:"f",assistant:"s",courier:"c"})[S.role]||"",
  ok=a=>!S||a[2].includes(role()),
  tx=a=>{const b=a[3]+" "+a[4]+" "+a[7]+" "+a[1];return{t:words(a[3]+" "+a[7]).map(stem),k:words(b).map(stem),s:words(a[5].join(" ")+" "+a[8].join(" ")).map(stem)}};
 const IDX=window.HELPX.map(a=>({a,x:tx(a)}));
 window.hlpFind=function(q,lim){const T=words(q).filter(w=>!STOP.has(w)&&!KKSTOP.has(w)&&w.length>1).map(stem);if(!T.length)return[];
  const sc=IDX.filter(e=>ok(e.a)).map(e=>{let hit=0,sc=0,kh=0;for(const w of T){const inT=e.x.t.some(x=>x.startsWith(w)||w.startsWith(x)&&x.length>=4),inK=e.x.k.some(x=>x.startsWith(w)||w.startsWith(x)&&x.length>=4),inS=e.x.s.some(x=>x.startsWith(w));if(inT||inK||inS)hit++;if(inT||inK)kh++;sc+=(inT?4:0)+(inK?2:0)+(inS?1:0)}return{a:e.a,hit,sc,kh}}).filter(r=>r.kh>0&&(r.hit===T.length||(T.length>2&&r.hit>=T.length-1&&r.hit>0))).sort((x,y)=>y.hit-x.hit||y.sc-x.sc);
  return sc.slice(0,lim||6).map(r=>r.a)};
 window.hlpAll=function(){return window.HELPX.filter(ok)};
 /* в казахском тексте названия кнопок в «ёлочках» берутся из словаря интерфейса, чтобы совпадали с тем, что на экране */
 const kq=x=>LANG==="kk"?String(x).replace(/«([^»]+)»/g,(m,y)=>{let v=y;try{v=t(y)}catch(e){}return v&&v!==y?"«"+v+"»":m}):x;
 window.hlpTitle=a=>LANG==="kk"?kq(a[7]):a[3];
 window.hlpSteps=a=>LANG==="kk"?a[8].map(kq):a[5];
 window.hlpRow=a=>`<div class="ln hlr" data-a="hlp_art" data-id="${a[0]}" role="button" tabindex="0"><span><b>${esc(hlpTitle(a))}</b><br><span class="mut">${esc(LANG==="kk"?kkCat(a[1]):a[1])}</span></span><span class="mut">›</span></div>`;
 const KC={"Начало":"Бастау","Заказы":"Заказдар","Доставка":"Жеткізу","Склад":"Склад","Клиенты и чаты":"Клиенттер және чаттар","Команда и отчёты":"Команда және есептер","Деньги и настройки":"Ақша және баптаулар"};
 window.kkCat=c=>KC[c]||c;
 window.hlpArt=function(id){const a=window.HELPX.find(x=>x[0]===id);if(!a)return;const go=a[6],tabOk=go&&((window.HPL||[]).some(t=>t[0]===go)||go==="set"||go==="me"||go==="help");
  modal(`<h1 style="font-size:22px">${esc(hlpTitle(a))}</h1><p class="mut" style="margin:0 0 8px">${esc(LANG==="kk"?kkCat(a[1]):a[1])}</p><ol class="hlp-steps">${hlpSteps(a).map(x=>`<li>${esc(x)}</li>`).join("")}</ol><div class="acts">${tabOk?`<button class="btn" type="button" data-a="goto" data-id="${go}" onclick="modal('')">${LANG==="kk"?"Бөлімді ашу":"Открыть раздел"}</button>`:""}<button class="btn g" type="button" data-a="hlp_all">${LANG==="kk"?"Барлық көмек":"Вся справка"}</button></div>`)};
})();
/* список по разделам или по запросу; частые вопросы по роли */
window.hlpList=function(q){q=String(q||"").trim();if(q){const r=hlpFind(q,20);return r.length?'<div class="card">'+r.map(hlpRow).join("")+"</div>":'<p class="mut">Ничего не нашлось. Попробуйте другими словами, например: «склад», «оплата», «доставка». Не нашли ответ — спросите администратора.</p>'}
 const cats=[];hlpAll().forEach(a=>{if(!cats.includes(a[1]))cats.push(a[1])});return cats.map(c=>`<h2>${esc(LANG==="kk"?kkCat(c):c)}</h2><div class="card">${hlpAll().filter(a=>a[1]===c).map(hlpRow).join("")}</div>`).join("")};
window.hlpPopular=function(){const P={o:["stockfill","neworder","pay","hours","reports","team"],a:["neworder","stockfill","checkrep","team","reports","dvpost"],p:["neworder","pay","paid","chats","dvpost","accept"],f:["assemble","stockfill","writeoff","reports","showcase","handover"],s:["assemble","showcase","stockfill","writeoff","reports"],c:["courier","map","push","net"]}[own()?"o":({admin:"a",operator:"p",florist:"f",assistant:"s",courier:"c"})[S.role]||"a"]||[];return P.map(id=>window.HELPX.find(a=>a[0]===id)).filter(Boolean)};
